const input = $input.first();
const csvData = input.json.body || '';
const lines = csvData.trim().split('\n');

if (lines.length < 2) {
  throw new Error('CSV must have a header row and at least one data row');
}

const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_'));

// Define expected schema
const expectedColumns = ['id', 'name', 'email', 'amount', 'date', 'status'];
const missingColumns = expectedColumns.filter(c => !headers.includes(c));
const extraColumns = headers.filter(c => !expectedColumns.includes(c));

if (missingColumns.length > 0) {
  throw new Error(`Missing required columns: ${missingColumns.join(', ')}`);
}

const rows = [];
const errors = [];

for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',').map(v => v.trim());
  if (values.length !== headers.length) {
    errors.push({ row: i + 1, error: `Expected ${headers.length} columns, got ${values.length}` });
    continue;
  }

  const row = {};
  headers.forEach((h, idx) => { row[h] = values[idx]; });

  // Validate email format
  if (row.email && !/^[^@]+@[^@]+\.[^@]+$/.test(row.email)) {
    errors.push({ row: i + 1, error: `Invalid email: ${row.email}` });
    continue;
  }

  // Validate amount is numeric
  if (row.amount && isNaN(parseFloat(row.amount))) {
    errors.push({ row: i + 1, error: `Invalid amount: ${row.amount}` });
    continue;
  }

  rows.push(row);
}

return [{
  json: {
    valid_rows: rows,
    validation_errors: errors,
    total_rows: lines.length - 1,
    valid_count: rows.length,
    error_count: errors.length,
    headers: headers,
    schema_valid: missingColumns.length === 0,
    extra_columns: extraColumns
  }
}];

const data = $input.first().json;
const rows = data.valid_rows;

const cleaned = rows.map(row => ({
  id: row.id.trim(),
  name: row.name.trim().replace(/\s+/g, ' '),
  email: row.email.trim().toLowerCase(),
  amount: parseFloat(row.amount).toFixed(2),
  date: new Date(row.date).toISOString().split('T')[0],
  status: row.status.trim().toUpperCase(),
  imported_at: new Date().toISOString()
}));

return cleaned.map(row => ({ json: row }));

const validationData = $('Validate CSV Schema').first().json;
const insertedCount = $('Bulk Insert to PostgreSQL').all().length || validationData.valid_count;

return [{
  json: {
    upload_timestamp: new Date().toISOString(),
    total_rows_received: validationData.total_rows,
    rows_inserted: validationData.valid_count,
    rows_rejected: validationData.error_count,
    validation_errors: JSON.stringify(validationData.validation_errors),
    status: validationData.error_count > 0 ? 'PARTIAL_SUCCESS' : 'SUCCESS'
  }
}];
